import axios from "axios";
import React, { useEffect } from "react";
import { useNavigate } from "react-router-dom";

export default function Analytics() {
    const navigate = useNavigate();

    useEffect(() => {
        axios
        .get(`http://localhost:5000/api/v1/analytics`)
        
    })
    return (
        <>
        <h2>Analytics</h2>
        </>
    )
}
